const d = $json;

const SYSTEM = "You write short, personal marketing emails for a luxury watch dealer. Write in the customer's language (ISO code given). Friendly and elegant, not pushy, max 150 words. Mention each watch with its price in USD. Only use the facts given. Plain text, no markdown. End with the business name and the line: 'Reply STOP to unsubscribe.' (translated into the customer's language).";
const SCHEMA = {
  "type": "object",
  "properties": {
    "subject": {
      "type": "string"
    },
    "body": {
      "type": "string"
    }
  },
  "required": [
    "subject",
    "body"
  ],
  "additionalProperties": false
};
const userContent = `Business: ${d.business_name}
Customer name: ${d.name || ''}
Customer language: ${d.language}
Watches that match their interests (JSON):
${JSON.stringify(d.watches)}`;

return {
  json: {
    claude_request: {
      model: 'claude-opus-5',
      max_tokens: 16000,
      fallbacks: 'default',              // if the model declines, Anthropic retries on a fallback model
      system: SYSTEM,
      messages: [{ role: 'user', content: userContent }],
      output_config: {
        effort: 'medium',             // low / medium / high: more effort = better answers, more cost
        format: { type: 'json_schema', schema: SCHEMA },
      },
    },
  },
};

// Read Claude's answer. The answer is JSON because we asked for a JSON schema.
const res = $json;
if (res.stop_reason === 'refusal') {
  throw new Error('Claude declined this request: ' + JSON.stringify(res.stop_details || {}));
}
const text = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
if (!text) {
  throw new Error('Claude returned no text: ' + JSON.stringify(res).slice(0, 500));
}
const ai = JSON.parse(text);

const d = $('Customers with new matches').item.json;
return { json: { ...d, subject: ai.subject, body: ai.body, watch_ids: d.watches.map(w => w.watch_id) } };

